    w.SetMiniMapEnabled(true);                                   // enable: gui not queried, flag kept
    if (g_gui.Calls != 1 || !w.MiniMapEnabled || !w.MiniMapActiveBeforeDisabled) { std::printf("0049ea10_TEST FAIL\n"); return 1; }
